      <span class="currency">USD</span>
      <img class="flag-small" src="__PLACEHOLDER_ASSETS_BASE_DIR__/011.png" width="25" height="18" alt="United States">
      <span class="help btn">?</span>
      <button class="btn">Register</button>
      <button class="btn">Sign in</button>
    </div>
    <nav class="nav">
      <div class="nav-item btn"><span class="ico">▣</span>Stays</div>
      <div class="nav-item btn"><span class="ico">✈</span>Flights</div>
      <div class="nav-item btn"><span class="ico">♧</span>Flight + Hotel</div>
      <div class="nav-item btn"><span class="ico">▱</span>Car rental</div>
      <div class="nav-item btn"><span class="ico">♙</span>Cruises</div>
      <div class="nav-item active btn"><span class="ico">♧</span>Activities</div>
      <div class="nav-item btn"><span class="ico">▤</span>Airport taxis</div>
    </nav>
  </div>
</header>

<main class="page">
  <div class="back btn"><span>‹</span> Ticket options</div>
  <div class="columns">
    <section>
      <div class="step">Step 1 of 2</div>
      <h1>General Admission to Universal Studios Hollywood</h1>
      <div class="alert"><span class="alert-icon">!</span>Your selected date is unavailable – choose another</div>
      <div class="hosted">This experience is hosted by a <a class="btn" href="#">business</a></div>

      <h2>Your details</h2>
      <div class="saved btn"><span class="person-icon"></span><a class="btn" href="#">Sign in to use your saved details</a></div>

      <form class="form" novalidate>
        <div class="row">
          <div class="field half" id="firstField">
            <label for="first">First Name <span class="required">*</span></label>
            <input class="btn" id="first" type="text" autocomplete="off">
          </div>
          <div class="field half" id="lastField">
            <label for="last">Last name <span class="required">*</span></label>
            <input class="btn" id="last" type="text" autocomplete="off">
          </div>
        </div>

        <div class="field full" id="emailField">
          <label for="email">Email Address <span class="required">*</span></label>
          <input class="btn" id="email" type="text" autocomplete="off">
          <div class="hint" id="emailHint" style="display:none"></div>
          <div class="error" id="emailError" style="display:none">Enter a valid email address</div>
        </div>

        <div class="field full">
          <label for="phone">Phone (mobile number preferred) <span class="required">*</span></label>
          <div class="phone-wrap">
            <div class="country btn">
              <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/011.png" width="25" height="18" alt="US">
              <span class="chevron">⌄</span>
            </div>
            <div class="phone-input">
              <input class="btn" id="phone" type="text" placeholder="+1" autocomplete="off">
            </div>
          </div>
        </div>

        <div class="reservation">
          <h2>Reservation details</h2>
          <div class="spinner"></div>
        </div>
      </form>

      <div class="legal">
        <p>By clicking "Next: Payment details" and completing a booking, you agree with the <a class="btn" href="#">terms and conditions</a> of Booking.com and the privacy policy of Musement.</p>
        <p>Please see our Privacy Statement to understand how we use and protect your personal information.<br><a class="btn" href="#">Privacy Statement</a></p>
      </div>
    </section>
